@Component("policy-handler")
@ProcessingGroup("policy-processing-group")
public class PolicyEventHandler {
	
	// core constructor
	PolicyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePolicyEvent
     */
    @EventHandler
    public void handle( CreatePolicyEvent event) {
        entityManager.persist(new Policy(event.getPolicyId(), event.getPolicyNumber(), event.getName(), event.getEffectiveDate(), event.getDescription(), event.getOrganization(), event.getAcknowledgements()));
    }

    /*
     * @param	event UpdatePolicyEvent
     */
    @EventHandler
    public Policy handle( UpdatePolicyEvent event) {
    	entityManager.merge(new Policy(event.getPolicyId(), event.getPolicyNumber(), event.getName(), event.getEffectiveDate(), event.getDescription(), event.getOrganization(), event.getAcknowledgements()));
    }
    
    /*
     * @param	event DeletePolicyEvent
     */
    @EventHandler
    public void on( DeletePolicyEvent event) {
    	Policy entity = new Policy();
   
    	// ------------------------------------------
    	// apply the PolicyId
    	// ------------------------------------------
    	entity.setPolicyId( event.getPolicyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PolicyRepository policyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PolicyEventHandler.class.getName());

}
